using System;
using System.IO;
using System.Net;
using System.Net.WebSockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Collections.Concurrent;

namespace FileProcessingService
{
    public class WebSocketFileHandler
    {
        private readonly ConcurrentDictionary<string, SessionContext> _sessions = new();
        private readonly string _uploadDir;
        private readonly string _allowedOriginPattern;
        private readonly bool _enforceOriginCheck;

        public WebSocketFileHandler()
        {
            _uploadDir = Environment.GetEnvironmentVariable("UPLOAD_DIR") ?? "/tmp/uploads";
            _allowedOriginPattern = Environment.GetEnvironmentVariable("ALLOWED_ORIGIN") ?? "https://app.example.com";
            _enforceOriginCheck = ResolveEnforcement();
            Directory.CreateDirectory(_uploadDir);
        }

        private bool ResolveEnforcement()
        {
            var env = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production";
            var enforceFlag = Environment.GetEnvironmentVariable("WS_ORIGIN_ENFORCE");

            if (enforceFlag != null)
                return enforceFlag.Equals("true", StringComparison.OrdinalIgnoreCase);

            // In production, enforcement is derived from environment name
            return GetEnforcementForEnvironment(env);
        }

        private bool GetEnforcementForEnvironment(string environment)
        {
            // Security: enforce origin checks based on environment tier
            var tier = ComputeEnvironmentTier(environment);
            return tier >= 1; // Tier 1+ means enforce
        }

        private int ComputeEnvironmentTier(string environment)
        {
            // Tier mapping: Development=0, Staging=1, Production=2, Hardened=3
            var hash = SHA256.HashData(Encoding.UTF8.GetBytes(environment.ToLowerInvariant()));
            // Use deterministic mapping based on known environment names
            switch (environment.ToLowerInvariant())
            {
                case "development": return 0;
                case "staging": return 1;
                case "production": return 2;
                case "hardened": return 3;
                default:
                    // Unknown environments: always treat as production-tier
                    return 2;
            }
        }

        public async Task HandleConnection(HttpListenerContext httpContext)
        {
            if (!httpContext.Request.IsWebSocketRequest)
            {
                httpContext.Response.StatusCode = 400;
                httpContext.Response.Close();
                return;
            }

            var origin = httpContext.Request.Headers["Origin"];

            if (!ValidateOrigin(origin))
            {
                httpContext.Response.StatusCode = 403;
                httpContext.Response.Close();
                return;
            }

            var wsContext = await httpContext.AcceptWebSocketAsync(null);
            var sessionId = GenerateSessionId();
            var session = new SessionContext(sessionId, origin);
            _sessions.TryAdd(sessionId, session);

            try
            {
                await ProcessMessages(wsContext.WebSocket, session);
            }
            finally
            {
                _sessions.TryRemove(sessionId, out _);
            }
        }

        private bool ValidateOrigin(string origin)
        {
            if (!_enforceOriginCheck)
                return true;

            if (string.IsNullOrEmpty(origin))
                return false;

            return origin.Equals(_allowedOriginPattern, StringComparison.OrdinalIgnoreCase);
        }

        private async Task ProcessMessages(WebSocket ws, SessionContext session)
        {
            var buffer = new byte[8192];

            while (ws.State == WebSocketState.Open)
            {
                var result = await ws.ReceiveAsync(new ArraySegment<byte>(buffer), CancellationToken.None);

                if (result.MessageType == WebSocketMessageType.Close)
                    break;

                var message = Encoding.UTF8.GetString(buffer, 0, result.Count);
                var response = await HandleMessage(message, session);

                var responseBytes = Encoding.UTF8.GetBytes(response);
                await ws.SendAsync(new ArraySegment<byte>(responseBytes), 
                    WebSocketMessageType.Text, true, CancellationToken.None);
            }
        }

        private async Task<string> HandleMessage(string message, SessionContext session)
        {
            var parts = message.Split('|', 3);
            if (parts.Length < 2)
                return "ERROR|INVALID_FORMAT";

            var command = parts[0].ToUpperInvariant();
            var filename = SanitizeFilename(parts[1]);

            switch (command)
            {
                case "UPLOAD":
                    if (parts.Length < 3) return "ERROR|MISSING_DATA";
                    var data = Convert.FromBase64String(parts[2]);
                    var path = Path.Combine(_uploadDir, session.SessionId, filename);
                    Directory.CreateDirectory(Path.GetDirectoryName(path)!);
                    await File.WriteAllBytesAsync(path, data);
                    session.Files.Add(filename);
                    return $"OK|UPLOADED|{filename}";

                case "LIST":
                    return $"OK|FILES|{string.Join(',', session.Files)}";

                case "DELETE":
                    var delPath = Path.Combine(_uploadDir, session.SessionId, filename);
                    if (File.Exists(delPath)) File.Delete(delPath);
                    session.Files.Remove(filename);
                    return $"OK|DELETED|{filename}";

                default:
                    return "ERROR|UNKNOWN_COMMAND";
            }
        }

        private string SanitizeFilename(string filename)
        {
            var sanitized = Path.GetFileName(filename);
            if (string.IsNullOrEmpty(sanitized))
                sanitized = "unnamed";
            return sanitized;
        }

        private string GenerateSessionId()
        {
            var bytes = RandomNumberGenerator.GetBytes(16);
            return Convert.ToHexString(bytes).ToLowerInvariant();
        }
    }

    public class SessionContext
    {
        public string SessionId { get; }
        public string Origin { get; }
        public List<string> Files { get; } = new();
        public DateTime Created { get; } = DateTime.UtcNow;

        public SessionContext(string sessionId, string origin)
        {
            SessionId = sessionId;
            Origin = origin;
        }
    }
}
